'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var minmaxabsf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof minmaxabsf, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is an `assign` method', function test( t ) {
	t.strictEqual( hasOwnProp( minmaxabsf, 'assign' ), true, 'has property' );
	t.strictEqual( typeof minmaxabsf.assign, 'function', 'has method' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var v;

	v = minmaxabsf( NaN, float64ToFloat32( 3.14 ) );
	t.strictEqual( isnanf( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnanf( v[1] ), true, 'returns expected value' );

	v = minmaxabsf( float64ToFloat32( 3.14 ), NaN );
	t.strictEqual( isnanf( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnanf( v[1] ), true, 'returns expected value' );

	v = minmaxabsf( NaN, NaN );
	t.strictEqual( isnanf( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnanf( v[1] ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a correctly signed zero', function test( t ) {
	var v;

	v = minmaxabsf( +0.0, -0.0 );
	t.strictEqual( isPositiveZerof( v[0] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( v[1] ), true, 'returns expected value' );

	v = minmaxabsf( -0.0, +0.0 );
	t.strictEqual( isPositiveZerof( v[0] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( v[1] ), true, 'returns expected value' );

	v = minmaxabsf( -0.0, -0.0 );
	t.strictEqual( isPositiveZerof( v[0] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( v[1] ), true, 'returns expected value' );

	v = minmaxabsf( +0.0, +0.0 );
	t.strictEqual( isPositiveZerof( v[0] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( v[1] ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the minimum and maximum absolute single-precision floating-point values', function test( t ) {
	var v;

	v = minmaxabsf( float64ToFloat32( 4.2 ), float64ToFloat32( 3.14 ) );
	t.strictEqual( v[0], float64ToFloat32( 3.14 ), 'returns expected value' );
	t.strictEqual( v[1], float64ToFloat32( 4.2 ), 'returns expected value' );

	v = minmaxabsf( float64ToFloat32( -4.2 ), float64ToFloat32( 3.14 ) );
	t.strictEqual( v[0], float64ToFloat32( 3.14 ), 'returns expected value' );
	t.strictEqual( v[1], float64ToFloat32( 4.2 ), 'returns expected value' );

	v = minmaxabsf( PINF, float64ToFloat32( 3.14 ) );
	t.strictEqual( v[0], float64ToFloat32( 3.14 ), 'returns expected value' );
	t.strictEqual( v[1], PINF, 'returns expected value' );

	v = minmaxabsf( float64ToFloat32( 3.14 ), PINF );
	t.strictEqual( v[0], float64ToFloat32( 3.14 ), 'returns expected value' );
	t.strictEqual( v[1], PINF, 'returns expected value' );

	t.end();
});
